SELECT DATE_TRUNC('MONTH', start_date) AS activity_month, status, DATE_TRUNC('QUARTER', start_date) AS quarter_start, SIZE(COLLECT_SET(plan)) AS num_plans, COUNT_IF(status = 'CANCELLED') AS cancelled_events, SIZE(COLLECT_SET(plan)) AS num_plans_2 FROM subscriptions GROUP BY DATE_TRUNC('MONTH', start_date), status, DATE_TRUNC('QUARTER', start_date) ORDER BY activity_month DESC NULLS LAST
